local card={api_version=1,id="LOOT_204",name="Cheat Death",text="<b>Secret:</b> When a friendly minion dies, return it to your hand.\nIt costs (2) less.",set="LOOTAPALOOZA",type="spell",class="rogue",rarity="common",cost=2,keywords={"secret"}}
card.triggers={{event="entity_died",timing="after",active_zones={"secret"},condition=function(ctx,self,event)return ctx:get_data(self,"triggered")==0 and event.player==ctx:controller(self)and ctx:entity(event.entity).type=="minion"and #ctx:hand(event.player)<10 end,effect=function(ctx,self,event)ctx:set_data(self,"triggered",1);ctx:reveal_secret(self);ctx:move(event.entity,"hand");cardlib.effects.modify(ctx, event.entity,{stat="cost",operation="add",value=-2,silenciable=true})end}}
return card
